/**
 * Real numbers for the HUD — generated by media/make_media.sh from this
 * run's judge outputs (never hand-edited): media/video/src/facts.json.
 * If facts.json is missing, `npm run build-facts` regenerates it from
 * media/verdict-good.json + verdict-baseline.json + selftest-kills.txt.
 */
import facts from "./facts.json";

export interface GateFact {
  name: string;
  detail: string;
  passed: boolean;
}

const good = facts.good;
const base = facts.baseline;

/** The 7 gate rows for the proof HUD, from the good site's verdict. */
export const Gates: { rows: GateFact[]; passText: string } = {
  rows: good.gates.map((g: { gate: string; passed: boolean; detail?: unknown }) => ({
    name: g.gate,
    detail: detail_text(g.gate, g.detail),
    passed: g.passed,
  })),
  passText: good.all_gates_passed
    ? `ALL ${good.gates.length} GATES PASS`
    : "GATES FAILED",
};

/** The baseline's real failed-gate names (the before/after contrast). */
export const BaselineFails: { names: string[]; count: number } = {
  names: base.gates.filter((g: { passed: boolean }) => !g.passed)
    .map((g: { gate: string }) => g.gate),
  count: base.gates.filter((g: { passed: boolean }) => !g.passed).length,
};

/** The wind widget's own computed sentence (untruncated, from the live DOM). */
export const WindWidgetSentence: { saving: string; label: string } = {
  saving: String(facts.wind_widget.saving_minutes),
  label: facts.wind_widget.label,
};

/** The self-test kill count (judge/selftest.sh output). */
export const KillCount: { text: string } = {
  text: facts.selftest_kills,
};

function detail_text(gate: string, detail: unknown): string {
  const d = (detail ?? {}) as Record<string, unknown>;
  switch (gate) {
    case "contrast_aa":
      return `min ratio ${d.min_ratio}:1 — WCAG AA, computed styles`;
    case "no_overflow":
      return `scrollWidth == clientWidth at 375/768/1440 px`;
    case "axe_a11y":
      return `axe-core 4.10.3 — zero critical/serious`;
    case "clean_load":
      return `0 console errors, 0 failed requests, 0 remote loads`;
    case "brief_sections":
      return `all 7 brief sections present in order`;
    case "taste_rules":
      return `15/15 measurable taste-skill rules pass`;
    case "wind_widget_sane":
      return `minutes sane — no negative or NaN`;
    default:
      return "";
  }
}
